-- 必须在滚动发布前显式执行；仅首次回填，已有自定义定义不会被覆盖。
BEGIN;
ALTER TABLE model_gateway.model_instances ADD COLUMN IF NOT EXISTS input_schema jsonb;
UPDATE model_gateway.model_instances SET input_schema = $schema${"$schema":"https://json-schema.org/draft/2020-12/schema","title":"vton","description":"试衣：images[0] 是人物图，images[1] 是服装图","x-category":"image_generation","type":"object","properties":{"images":{"type":"array","description":"试衣：images[0] 是人物图，images[1] 是服装图","items":{"type":"object","required":["mime_type","data"],"properties":{"mime_type":{"type":"string","description":"图片 MIME","pattern":"^image/[A-Za-z0-9.+-]+$"},"data":{"type":"string","description":"图片原始字节的 Base64，不含 data URL 前缀","minLength":1,"contentEncoding":"base64"}},"additionalProperties":false},"minItems":2,"maxItems":2},"prompt":{"type":"string","description":"试衣提示词"}},"required":["images"],"additionalProperties":false,"x-experimental-properties":{"use_pe":{"type":"string","description":"仅实验凭据可覆盖的生成参数"}}}$schema$::jsonb WHERE protocol = 'vton' AND input_schema IS NULL;
UPDATE model_gateway.model_instances SET input_schema = $schema${"$schema":"https://json-schema.org/draft/2020-12/schema","title":"body_model","description":"体模生成：一张人物图","x-category":"image_generation","type":"object","properties":{"images":{"type":"array","description":"体模生成：一张人物图","items":{"type":"object","required":["mime_type","data"],"properties":{"mime_type":{"type":"string","description":"图片 MIME","pattern":"^image/[A-Za-z0-9.+-]+$"},"data":{"type":"string","description":"图片原始字节的 Base64，不含 data URL 前缀","minLength":1,"contentEncoding":"base64"}},"additionalProperties":false},"minItems":1,"maxItems":1},"gender":{"type":"string","description":"原样交给模型服务的性别参数"}},"required":["images"],"additionalProperties":false,"x-experimental-properties":{"prompt":{"type":"string","description":"仅实验凭据可覆盖的生成参数"}}}$schema$::jsonb WHERE protocol = 'body_model' AND input_schema IS NULL;
UPDATE model_gateway.model_instances SET input_schema = $schema${"$schema":"https://json-schema.org/draft/2020-12/schema","title":"product_generation","description":"商品图生成：一张服装原图","x-category":"image_generation","type":"object","properties":{"images":{"type":"array","description":"商品图生成：一张服装原图","items":{"type":"object","required":["mime_type","data"],"properties":{"mime_type":{"type":"string","description":"图片 MIME","pattern":"^image/[A-Za-z0-9.+-]+$"},"data":{"type":"string","description":"图片原始字节的 Base64，不含 data URL 前缀","minLength":1,"contentEncoding":"base64"}},"additionalProperties":false},"minItems":1,"maxItems":1},"garment_name":{"type":"string","description":"衣物名称"},"garment_role":{"type":"string","description":"衣物角色"}},"required":["images"],"additionalProperties":false}$schema$::jsonb WHERE protocol = 'product_generation' AND input_schema IS NULL;
UPDATE model_gateway.model_instances SET input_schema = $schema${"$schema":"https://json-schema.org/draft/2020-12/schema","title":"garment_extraction","description":"人物拆衣：第一张人物图，第二张可选的人体解析 mask","x-category":"image_generation","type":"object","properties":{"images":{"type":"array","description":"人物拆衣：第一张人物图，第二张可选的人体解析 mask","items":{"type":"object","required":["mime_type","data"],"properties":{"mime_type":{"type":"string","description":"图片 MIME","pattern":"^image/[A-Za-z0-9.+-]+$"},"data":{"type":"string","description":"图片原始字节的 Base64，不含 data URL 前缀","minLength":1,"contentEncoding":"base64"}},"additionalProperties":false},"minItems":1,"maxItems":2},"garment_name":{"type":"string","description":"衣物名称"},"garment_role":{"type":"string","description":"衣物角色"},"bbox":{"type":"array","items":{"type":"number"},"minItems":4,"maxItems":4},"bbox_format":{"type":"string","description":"bbox 坐标格式"},"parse_labels":{"type":"object","additionalProperties":{"type":"string"}}},"required":["images"],"additionalProperties":false,"anyOf":[{"properties":{"images":{"minItems":2}}},{"required":["bbox"]},{"required":["parse_labels"]}],"x-experimental-properties":{"prompt":{"type":"string","description":"仅实验凭据可覆盖的生成参数"},"use_pe":{"type":"string","description":"仅实验凭据可覆盖的生成参数"}}}$schema$::jsonb WHERE protocol = 'garment_extraction' AND input_schema IS NULL;
UPDATE model_gateway.model_instances SET input_schema = $schema${"$schema":"https://json-schema.org/draft/2020-12/schema","title":"outfit_video","description":"试衣视频：一张首帧人物图","x-category":"video_generation","type":"object","properties":{"images":{"type":"array","description":"试衣视频：一张首帧人物图","items":{"type":"object","required":["mime_type","data"],"properties":{"mime_type":{"type":"string","description":"图片 MIME","pattern":"^image/[A-Za-z0-9.+-]+$"},"data":{"type":"string","description":"图片原始字节的 Base64，不含 data URL 前缀","minLength":1,"contentEncoding":"base64"}},"additionalProperties":false},"minItems":1,"maxItems":1},"prompt":{"type":"string","description":"视频提示词"},"motion_tips":{"type":"string","description":"动作说明"}},"required":["images"],"additionalProperties":false,"x-experimental-properties":{"model":{"type":"string","description":"仅实验凭据可覆盖的生成参数"},"duration":{"type":"string","description":"仅实验凭据可覆盖的生成参数"},"resolution":{"type":"string","description":"仅实验凭据可覆盖的生成参数"},"fps":{"type":"string","description":"仅实验凭据可覆盖的生成参数"},"audio":{"type":"string","description":"仅实验凭据可覆盖的生成参数"}}}$schema$::jsonb WHERE protocol = 'outfit_video' AND input_schema IS NULL;
UPDATE model_gateway.model_instances SET input_schema = $schema${"$schema":"https://json-schema.org/draft/2020-12/schema","title":"human_parse","description":"人体和衣物解析","x-category":"human_parser","type":"object","properties":{"image":{"type":"string","description":"图片 Base64，不含 data URL 前缀","minLength":1,"contentEncoding":"base64"}},"required":["image"],"additionalProperties":false}$schema$::jsonb WHERE protocol = 'human_parse' AND input_schema IS NULL;
UPDATE model_gateway.model_instances SET input_schema = $schema${"$schema":"https://json-schema.org/draft/2020-12/schema","title":"human_yolo","description":"人体检测","x-category":"person_detect","type":"object","properties":{"image":{"type":"string","description":"图片 Base64，不含 data URL 前缀","minLength":1,"contentEncoding":"base64"},"file":{"type":"string","description":"图片 Base64，不含 data URL 前缀","minLength":1,"contentEncoding":"base64"},"conf":{"oneOf":[{"type":"string"},{"type":"number"}]},"iou":{"oneOf":[{"type":"string"},{"type":"number"}]}},"required":[],"additionalProperties":false,"anyOf":[{"required":["image"]},{"required":["file"]}]}$schema$::jsonb WHERE protocol = 'human_yolo' AND input_schema IS NULL;
UPDATE model_gateway.model_instances SET input_schema = $schema${"$schema":"https://json-schema.org/draft/2020-12/schema","title":"face_compare","description":"人脸相似度比较，两张人脸图片","x-category":"face_compare","type":"object","properties":{"image_a":{"type":"string","description":"图片 Base64，不含 data URL 前缀","minLength":1,"contentEncoding":"base64"},"image_b":{"type":"string","description":"图片 Base64，不含 data URL 前缀","minLength":1,"contentEncoding":"base64"},"file_a":{"type":"string","description":"图片 Base64，不含 data URL 前缀","minLength":1,"contentEncoding":"base64"},"file_b":{"type":"string","description":"图片 Base64，不含 data URL 前缀","minLength":1,"contentEncoding":"base64"},"face_index_a":{"oneOf":[{"type":"integer"},{"type":"string"}]},"face_index_b":{"oneOf":[{"type":"integer"},{"type":"string"}]}},"required":[],"additionalProperties":false,"allOf":[{"anyOf":[{"required":["image_a"]},{"required":["file_a"]}]},{"anyOf":[{"required":["image_b"]},{"required":["file_b"]}]}]}$schema$::jsonb WHERE protocol = 'face_compare' AND input_schema IS NULL;
UPDATE model_gateway.model_instances SET input_schema = $schema${"$schema":"https://json-schema.org/draft/2020-12/schema","title":"lens_correction","description":"镜头畸变校正","x-category":"image_processing","type":"object","properties":{"base64":{"type":"string","description":"图片 Base64，不含 data URL 前缀","minLength":1,"contentEncoding":"base64"},"mirror_lens":{"type":"boolean"},"crop":{"type":"boolean"},"sampler":{"type":"string","description":"采样方式"},"preset":{"type":"string","description":"校正预设"}},"required":["base64"],"additionalProperties":false}$schema$::jsonb WHERE protocol = 'lens_correction' AND input_schema IS NULL;
UPDATE model_gateway.model_instances SET input_schema = $schema${"$schema":"https://json-schema.org/draft/2020-12/schema","title":"segment_person","description":"人物抠图","x-category":"segment","type":"object","properties":{"image":{"type":"string","description":"图片 Base64，不含 data URL 前缀","minLength":1,"contentEncoding":"base64"},"file":{"type":"string","description":"图片 Base64，不含 data URL 前缀","minLength":1,"contentEncoding":"base64"},"method":{"type":"string","description":"抠图方法","minLength":1,"default":"person-birefnet-portrait"},"person_method":{"type":"string","description":"人物抠图方法"},"subject_method":{"type":"string","description":"主体抠图方法"},"preprocess":{"oneOf":[{"type":"string"},{"type":"boolean"}]},"output":{"type":"string","description":"结果格式，推荐 b64","default":"b64"},"trace_id":{"type":"string","description":"链路编号"}},"required":[],"additionalProperties":false,"anyOf":[{"required":["image"]},{"required":["file"]}]}$schema$::jsonb WHERE protocol = 'segment_person' AND input_schema IS NULL;
UPDATE model_gateway.model_instances SET input_schema = $schema${"$schema":"https://json-schema.org/draft/2020-12/schema","title":"segment_subject","description":"主体抠图","x-category":"segment","type":"object","properties":{"image":{"type":"string","description":"图片 Base64，不含 data URL 前缀","minLength":1,"contentEncoding":"base64"},"file":{"type":"string","description":"图片 Base64，不含 data URL 前缀","minLength":1,"contentEncoding":"base64"},"method":{"type":"string","description":"抠图方法","minLength":1,"default":"person-bria-rmbg"},"person_method":{"type":"string","description":"人物抠图方法"},"subject_method":{"type":"string","description":"主体抠图方法"},"preprocess":{"oneOf":[{"type":"string"},{"type":"boolean"}]},"output":{"type":"string","description":"结果格式，推荐 b64","default":"b64"},"trace_id":{"type":"string","description":"链路编号"}},"required":[],"additionalProperties":false,"anyOf":[{"required":["image"]},{"required":["file"]}]}$schema$::jsonb WHERE protocol = 'segment_subject' AND input_schema IS NULL;
UPDATE model_gateway.model_instances SET input_schema = $schema${"$schema":"https://json-schema.org/draft/2020-12/schema","title":"chat_completions","description":"对话和图片理解，保留 OpenAI-compatible 扩展参数","x-category":"chat","type":"object","properties":{"messages":{"type":"array","minItems":1,"items":{"type":"object","required":["role"],"properties":{"role":{"type":"string","description":"消息角色"},"content":{"oneOf":[{"type":"null"},{"type":"string"},{"type":"array","items":{"type":"object"}}]}},"additionalProperties":true}},"stream":{"type":"boolean"},"max_tokens":{"type":"integer","minimum":1},"temperature":{"type":"number"},"model_traits":{"type":"object"},"reasoning_effort":{"type":"string","description":"OpenAI-compatible 思考预算，原样转发；具体取值由本模型部署定义"},"chat_template_kwargs":{"type":"object","description":"vLLM 模板参数，例如 enable_thinking；以模型部署定义为准"},"max_completion_tokens":{"type":"integer","minimum":1},"response_format":{"type":"object","description":"OpenAI-compatible 输出格式，包含 type 及可选 json_schema"},"tools":{"type":"array","items":{"type":"object"}},"tool_choice":{"oneOf":[{"type":"string"},{"type":"object"}]}},"required":["messages"],"additionalProperties":true}$schema$::jsonb WHERE protocol = 'chat_completions' AND input_schema IS NULL;
UPDATE model_gateway.model_instances SET input_schema = $schema${"$schema":"https://json-schema.org/draft/2020-12/schema","title":"decision","description":"图片决策：恰好一张内联图片，预设 task 或用户问题二选一","x-category":"classification","type":"object","properties":{"messages":{"type":"array","minItems":1,"items":{"type":"object","required":["role"],"properties":{"role":{"type":"string","description":"消息角色"},"content":{"oneOf":[{"type":"null"},{"type":"string"},{"type":"array","items":{"type":"object"}}]}},"additionalProperties":true}},"stream":{"type":"boolean"},"max_tokens":{"type":"integer","minimum":1},"temperature":{"type":"number"},"model_traits":{"type":"object","properties":{"task":{"type":"string","description":"预设任务名称"},"options":{"type":"array","items":{"type":"string"}}},"additionalProperties":false}},"required":["messages"],"additionalProperties":true}$schema$::jsonb WHERE protocol = 'decision' AND input_schema IS NULL;
COMMIT;
